const input = $('Webhook').first().json.body.payload.body

const patterns = {
  hostname: /\/edit\s+([^\n,]+)/i,
  username: /user\s*:\s*([^\n,]+)/i,
  password: /pass\s*:\s*([^\n,]+)/i,
  ip: /ip\s*:\s*([^\n,]+)/i,
  port: /port\s*:\s*([^\n,]+)/i,
  status: /status\s*:\s*([^\n,]+)/i,
  group_name: /group\s*:\s*([^\n,]+)/i
};

let result = {};
let missing = [];

try {
  for (const key in patterns) {
    const match = input.match(patterns[key]);
    if (match) {
      result[key] = match[1].trim();
    }
  }

  if (!result.hostname) missing.push("hostname");
  if (!result.username) missing.push("username");
  if (!result.password) missing.push("password");

  if (missing.length) {
    return [
      {
        json: {
          success: false,
          error: `Missing required fields: ${missing.join(", ")}`,
          raw: input
        }
      }
    ];
  }

  return [
    {
      json: {
        success: true,
        ...result
      }
    }
  ];

} catch (e) {
  return [
    {
      json: {
        success: false,
        error: e.message,
        raw: input
      }
    }
  ];
}

const tokens = items.map(item => item.json);  // ambil semua token dari items
let msg = '📋 *Daftar API Token User:*

';

tokens.forEach((t, i) => {
  msg += `🆔 *User ID:* ${t.user_id}
👤 *Username:* ${t.username}
🔑 *Token:* ${t.token}
📅 *Created:* ${t.created_at}
⏳ *Expires:* ${t.expires_at}
`;
  if (i < tokens.length - 1) msg += '
---

';
});

return [{ json: { message: msg } }];

const msg = $('Webhook').first().json.body.payload.body || "";
const lower = msg.toLowerCase();
let command = "unknown"; let arg = msg.split(" ").slice(1).join(" ").trim();
if (lower.startsWith("/help")) command = "help";
else if (lower.startsWith("ping")) command = "ping-test";
else if (lower.startsWith("/ip")) command = "ip";
else if (lower.startsWith("/ping")) command = "ping";
else if (lower.startsWith("/cctv")) command = "cctv";
else if (lower.startsWith("/snap")) command = "snap";
else if (lower.startsWith("/edit")) command = "edit";
else if (lower.startsWith("/token-check")) command = "token-check";
else if (lower.startsWith("/whitelist add")) command = "whitelist-add";
else if (lower.startsWith("/whitelist remove")) command = "whitelist-remove";
return [{json:{command,arg}}];

const cameras = $input.first().json.cameras;

const all = cameras.map(cam => `${cam.hostname} (${cam.status})`).join('\n');

return [{
  json: {
    summary: all
  }
}];

const msg = $('Webhook').first().json.body.payload.body.trim();
const parts = msg.split(" ");

if (parts.length >= 4) {
  const phone_number = parts[2].replace(/\D/g, "");
  const name = parts.slice(3).join(" ").trim();

  return [{
    json: {
      phone_number,
      name
    }
  }];
} else {
  throw new Error("Invalid format. Use: /whitelist add <phone> <name>");
}

// Ambil isi string JSON dari pesan error
const raw = $json.error.message;
const jsonString = raw.split(" - ")[1].replace(/^"|"$/g, "").replace(/\\"/g, '"');

try {
  const parsed = JSON.parse(jsonString);
  const msg = parsed.detail?.[0]?.msg || "Unknown error";
  return [{ json: { msg } }];
} catch (e) {
  return [{ json: { msg: "Failed to parse error message." } }];
}

const msg = $('Webhook').first().json.body.payload.body.trim();
const parts = msg.split(" ");

// Expected format: /whitelist remove <phone_number>
if (parts.length === 3 && parts[0] === "/whitelist" && parts[1] === "remove") {
  const raw = parts[2].replace(/\D/g, "");

  // Optional: convert from 08xx to 628xx
  const phone_number = raw.startsWith("08") ? "628" + raw.slice(1) : raw;

  return [{
    json: {
      command: "remove_whitelist",
      phone_number
    }
  }];
} else {
  throw new Error("Invalid format. Use: /whitelist remove <phone_number>");
}

let nameResult = [];
let ipResult = [];

try {
  nameResult = $('Get snapshot by CCTV name').all()
    .filter(item => item.json && Object.keys(item.json).length > 0);
} catch (e) {
  nameResult = [];
}

try {
  ipResult = $('Get snapshot by CCTV IP').all()
    .filter(item => item.json && Object.keys(item.json).length > 0);
} catch (e) {
  ipResult = [];
}

let selectedResults = [];

if (nameResult.length > 0) {
  selectedResults = nameResult;
} else if (ipResult.length > 0) {
  selectedResults = ipResult;
}

if (selectedResults.length === 0) {
  return [{
    json: { cctvNotExist: true }
  }];
} else {
  return selectedResults.map(item => ({
    json: {
      ...item.json,
      cctvNotExist: false
    }
  }));
}
